sys_script_include.script:
var RegistrationValidatorUtils = Class.create();
RegistrationValidatorUtils.prototype = {
    initialize: function() {},

    checkUserAlredyRegistered: function(user) {
        if (!user) return false;

        var registration = new GlideRecord("x_2060759_base_m_0_registration");
        registration.addQuery("opened_by", user);
        registration.addNotNullQuery("base");
        registration.addQuery("state", "!=", "rejected"); // ⚠️ veja nota sobre state abaixo
        registration.setLimit(1);
        registration.query();

        return registration.hasNext();
    },

    checkBaseCapacity: function(maxCapacity, occupiedCapacity) {
        var maxCap = parseInt(maxCapacity, 10) || 0;
        var occCap = parseInt(occupiedCapacity, 10) || 0;

        // ✅ FIX: operator must be >= (not &gt;=)
        return occCap >= maxCap;
    },

    getAvailableBases: function() {
        var user = gs.getUserID();

        if (this.checkUserAlredyRegistered(user)) {
            return "sys_idISEMPTY";
        }

        var available = [];
        var base = new GlideRecord("x_2060759_base_m_0_bases");
        base.query();

        while (base.next()) {
            var maxCap = base.getValue("maximum_capacity");
            var occCap = base.getValue("occupied_capacity");

            if (!this.checkBaseCapacity(maxCap, occCap)) {
                available.push(base.getUniqueValue());
            }
        }

        return available.length
            ? ("sys_idIN" + available.join(","))
            : "sys_idISEMPTY";
    },

    type: "RegistrationValidatorUtils"
};
